   trace('a = [1, 2, 4, 3]\nn = len(a)\nfor i in range(n - 1):\n    swapped = False\n    for j in range(n - 1 - i):\n        if a[j] > a[j + 1]:\n            a[j], a[j + 1] = a[j + 1], a[j]\n            swapped = True\n    print(i + 1, "회전:", a)\n    if not swapped:\n        break', '2회전에서 교환이 없어 멈춰요'),
