  'n = int(input())\nstock = {}\nfirst = {}\nfor _ in range(n):\n    b, c = input().split()\n    stock[b] = int(c)\n    first[b] = int(c)\nwhile True:\n    line = input().split()\n    if line[0] == "종료":\n        break\n    cmd, b = line\n    if b not in stock:\n        print("없는 책입니다")\n    elif cmd == "대출":\n        if stock[b] == 0:\n            print("대출 불가")\n        else:\n            stock[b] -= 1\n            print(f"대출 완료 (남은 수량 {stock[b]})")\n    else:\n        if stock[b] == first[b]:\n            print("반납 오류")\n        else:\n            stock[b] += 1\n            print(f"반납 완료 (남은 수량 {stock[b]})")\nout = 0\nfor b in stock:\n    print(f"{b}: {stock[b]}")\n    out += first[b] - stock[b]\nprint(f"대출 중 {out}권")',
